# ==============================================================================# 049_ORCHESTRATOR.py# ==============================================================================import sqlite3from pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")# ==============================================================================# TABELA# ==============================================================================cur.execute("""CREATE TABLE IF NOT EXISTS orchestrator(    id INTEGER PRIMARY KEY AUTOINCREMENT,    created_at TEXT,    component TEXT,    priority TEXT,    action TEXT,    status TEXT)""")conn.commit()# ==============================================================================# LIMPA EXECUÃ‡Ã•ES READY# ==============================================================================cur.execute("DELETE FROM orchestrator WHERE status='READY'")conn.commit()# ==============================================================================# REGRAS# ==============================================================================# RULE ENGINEcur.execute("""SELECTrule_name,priority,actionFROM rule_engineWHERE status='READY'""")for row in cur.fetchall():    cur.execute("""    INSERT INTO orchestrator(        created_at,        component,        priority,        action,        status    )    VALUES(?,?,?,?,?)    """,(        datetime.now().isoformat(),        row["rule_name"],        row["priority"],        row["action"],        "READY"    ))# ==============================================================================# DISCO# ==============================================================================cur.execute("""SELECTdisk_free_gbFROM resourcesORDER BY id DESCLIMIT 1""")disk = cur.fetchone()if disk:    free = disk["disk_free_gb"]    if free < 5:        cur.execute("""        INSERT INTO orchestrator(            created_at,            component,            priority,            action,            status        )        VALUES(?,?,?,?,?)        """,(            datetime.now().isoformat(),            "RESOURCE_MANAGER",            "CRITICAL",            "FREE_DISK_SPACE",            "READY"        ))conn.commit()# ==============================================================================# DASHBOARD# ==============================================================================print("="*80)print("ORCHESTRATOR")print("="*80)cur.execute("""SELECTpriority,component,action,statusFROM orchestratorORDER BYCASE priorityWHEN 'CRITICAL' THEN 1WHEN 'HIGH' THEN 2WHEN 'NORMAL' THEN 3WHEN 'LOW' THEN 4END,id""")rows = cur.fetchall()for row in rows:    print(        f"{row['priority']:<10}"        f"{row['component']:<28}"        f"{row['action']:<32}"        f"{row['status']}"    )print("="*80)cur.execute("SELECT COUNT(*) FROM orchestrator")print("AÃ‡Ã•ES ORQUESTRADAS:", cur.fetchone()[0])print("="*80)conn.close()

